NEW_FILES = {'packages/service/design.py': '"""A level as a saved design: the templates a designer starts from, the controls each offers, and the document a\ndesign is saved as (the factory\'s roadmap 312 and 313; `docs/AUTHORING_LOOP.md`).\n\nTHREE KINDS OF STATE, the no-AI authoring plan\'s section 7: the DESIGN is authored source -- the template, the\nchoices, the intent -- saved and versioned, edited only through operations; the brief the pipeline reads is\nDERIVED from it (`brief_from_design`) and recorded with each build; generated output is rebuilt, never edited.\n\nEVERY CONTROL IS TRUTHFUL. `capabilities` lists each control a template offers with its support state:\n``supported`` (a consumer reads it and the level changes), ``conditional`` (it does, with a stated substitution),\n``intent`` (saved for the designer and for review; nothing builds from it yet). Option lists are read off the\nowning code -- the road grammars, the surroundings, the times `_preset_for` resolves -- so a control cannot offer a\nvalue its consumer does not know. `tests/service/test_design.py` holds both directions.\n\nA DESIGN LIVES OUTSIDE THE GODOT PROJECT AND THE TOOL REPOS: ``<factory>/levels/<slug>/design.json``, its factory\nworkspace beside it in ``workspace/`` once a build makes one. ``levels`` is where START_HERE.md already puts a first\nlevel, and the doctor\'s long-path check already measures it.\n"""\nfrom __future__ import annotations\n\nimport json\nimport os\nimport re\nimport time\nimport uuid\nfrom pathlib import Path\n\nDESIGN_SCHEMA = "gabagool.design.v1"\nTEMPLATE_SCHEMA = "gabagool.template.v1"\nTEMPLATES_DIR = Path(__file__).resolve().parent / "templates"\nDESIGN_FILE = "design.json"\nDESIGN_KEYS = {"schema", "design_id", "revision", "template", "name", "slug", "choices", "intent",\n               "created_at", "updated_at"}\n#: The candidate counts the planner is asked for; `FactoryService.validate_brief`\'s range.\nCANDIDATES = (1, 8)\n\n\nclass DesignError(ValueError):\n    """A design or a change to one that cannot be accepted; ``code`` is the stable reason."""\n\n    def __init__(self, code: str, message: str) -> None:\n        super().__init__(message)\n        self.code = code\n\n\n# ---- templates ------------------------------------------------------------------------------------------------\n\ndef templates() -> dict[str, dict]:\n    """Every template shipped beside this module, by id."""\n    out = {}\n    for p in sorted(TEMPLATES_DIR.glob("*.json")):\n        t = json.loads(p.read_text(encoding="utf-8"))\n        if t.get("schema") != TEMPLATE_SCHEMA:\n            raise DesignError("template_unreadable", "%s is not a %s" % (p.name, TEMPLATE_SCHEMA))\n        out[t["template_id"]] = t\n    return out\n\n\ndef template(template_id: str) -> dict:\n    t = templates().get(template_id)\n    if t is None:\n        raise DesignError("unknown_template", "no template %r; known: %s" % (template_id, ", ".join(templates())))\n    return t\n\n\n# ---- the capability catalog -----------------------------------------------------------------------------------\n\n_TIMES = (("morning", "Morning"), ("noon", "High noon"), ("afternoon", "Afternoon"), ("evening", "Evening"),\n          ("midnight", "Midnight"))\n_GRAMMAR_LABELS = {"T": "One street (a T junction)", "cross": "Crossroads",\n                   "block": "A block with a service lane behind (a loop)"}\n_SURROUNDING_LABELS = {"": "Chosen by the level", "borough": "More of the borough", "none": "Nothing (the plate\'s edge)",\n                       "yards": "Rail and freight yards", "parkland": "Parkland", "roadside": "Roadside lots"}\n_INTENT_LABELS = {"route_shape": "Route shape", "objective_hypotheses": "Objective steps",\n                  "extraction_relationship": "Way out", "verticality": "Verticality", "landmark": "Landmark",\n                  "seed_policy": "Seed policy"}\n\n\ndef capabilities(template_id: str) -> list[dict]:\n    """The controls a template offers, in form order, each with its support state, its options or range, its\n    default (the template\'s own value), and what reads it."""\n    from apps.cli.commands import UNBUILT_BRIEF_FIELDS\n    from packages.pipeline.road_grammar import GRAMMARS\n    from packages.pipeline.site_variation import SURROUNDINGS\n\n    brief = template(template_id)["brief"]\n    grammar = str(brief.get("road_grammar") or "T")\n    rows = [\n        {"key": "name", "label": "Level name", "type": "text", "default": template(template_id)["label"],\n         "support": "supported", "consumer": "the level\'s display name and its folder"},\n        {"key": "time_of_day", "label": "Time of day", "type": "choice",\n         "options": [{"value": v, "label": lbl} for v, lbl in _TIMES], "default": brief.get("time_of_day", "afternoon"),\n         "support": "supported", "consumer": "the Lux lighting preset (apps.cli.commands._preset_for)",\n         "rebuilds": "lighting"},\n        {"key": "weather", "label": "Weather", "type": "choice",\n         "options": [{"value": "clear", "label": "Clear"},\n                     {"value": "rain", "label": "Rain (an overcast day: it replaces the time of day)"}],\n         "default": brief.get("weather", "clear"), "support": "conditional",\n         "note": "Rain replaces the time of day: it is the Heavy Rain look, an overcast day.",\n         "consumer": "the Lux lighting preset (apps.cli.commands._preset_for)", "rebuilds": "lighting"},\n        {"key": "road_grammar", "label": "Streets", "type": "choice",\n         "options": [{"value": g, "label": _GRAMMAR_LABELS.get(g, g)} for g in GRAMMARS], "default": grammar,\n         "support": "supported", "consumer": "the site\'s road graph (packages.pipeline.road_grammar)",\n         "rebuilds": "layout"},\n        {"key": "surroundings", "label": "Beyond the edge", "type": "choice",\n         "options": [{"value": s, "label": _SURROUNDING_LABELS.get(s, s)} for s in ("",) + tuple(SURROUNDINGS)],\n         "default": str(brief.get("surroundings") or ""), "support": "supported",\n         "consumer": "the backdrop recipe (packages.pipeline.site_variation)", "rebuilds": "backdrop"},\n        {"key": "candidate_count", "label": "Layouts to generate", "type": "integer", "min": CANDIDATES[0],\n         "max": CANDIDATES[1], "default": int(brief.get("candidate_count", 3)), "support": "supported",\n         "consumer": "the planner\'s candidate seeds (packages.pipeline.planner)", "rebuilds": "layout"},\n        {"key": "roof_props", "label": "Roof clutter", "type": "boolean", "default": bool(brief.get("roof_props", True)),\n         "support": "supported", "consumer": "Zoo\'s rooftop scatter", "rebuilds": "art"},\n    ]\n    for key in UNBUILT_BRIEF_FIELDS:\n        value = brief.get(key, [] if key == "objective_hypotheses" else "")\n        rows.append({"key": key, "label": _INTENT_LABELS.get(key, key),\n                     "type": "list" if isinstance(value, list) else "text", "default": value, "support": "intent",\n                     "note": "Saved with the level for you and for review; nothing builds from it yet."})\n    rows.append({"key": "notes", "label": "Notes", "type": "longtext", "default": "", "support": "intent",\n                 "note": "For you and for review. Writing here does not change what is built."})\n    return rows\n\n\ndef _controls(template_id: str) -> dict[str, dict]:\n    return {c["key"]: c for c in capabilities(template_id)}\n\n\ndef check_value(control: dict, value):\n    """``value`` for ``control``, or `DesignError` naming what is wrong with it."""\n    key, kind = control["key"], control["type"]\n    if kind == "choice":\n        allowed = [o["value"] for o in control["options"]]\n        if value not in allowed:\n            raise DesignError("bad_choice", "%s must be one of %s, not %r" % (key, allowed, value))\n    elif kind == "integer":\n        if isinstance(value, bool) or not isinstance(value, int) or not control["min"] <= value <= control["max"]:\n            raise DesignError("bad_choice", "%s must be a whole number from %d to %d" % (key, control["min"],\n                                                                                     control["max"]))\n    elif kind == "boolean":\n        if not isinstance(value, bool):\n            raise DesignError("bad_choice", "%s must be true or false" % key)\n    elif kind == "list":\n        if not isinstance(value, list) or not all(isinstance(v, str) for v in value):\n            raise DesignError("bad_choice", "%s must be a list of words" % key)\n    elif not isinstance(value, str):\n        raise DesignError("bad_choice", "%s must be text" % key)\n    return value\n\n\n# ---- the design document --------------------------------------------------------------------------------------\n\ndef _now() -> str:\n    return time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime())\n\n\ndef slugify(name: str) -> str:\n    s = re.sub(r"[^a-z0-9]+", "_", name.strip().lower()).strip("_")\n    return (s or "level")[:40]\n\n\ndef levels_root(factory_root: Path) -> Path:\n    return Path(factory_root) / "levels"\n\n\ndef new_design(template_id: str, name: str, choices: dict | None = None, intent: dict | None = None) -> dict:\n    """A revision-1 design from a template, its controls at the template\'s defaults but for ``choices`` and\n    ``intent``, each checked against the catalog."""\n    controls = _controls(template_id)\n    if not isinstance(name, str) or not name.strip():\n        raise DesignError("bad_choice", "a level needs a name")\n    ch, it = {}, {}\n    for key, c in controls.items():\n        if key == "name":\n            continue\n        (ch if c["support"] in ("supported", "conditional") else it)[key] = c["default"]\n    for given, into, kinds in ((choices or {}, ch, ("supported", "conditional")), (intent or {}, it, ("intent",))):\n        for key, value in given.items():\n            c = controls.get(key)\n            if c is None or c["support"] not in kinds:\n                raise DesignError("unknown_control", "%s is not a %s control of %s" % (\n                    key, "choice" if kinds[0] == "supported" else "intent", template_id))\n            into[key] = check_value(c, value)\n    now = _now()\n    return {"schema": DESIGN_SCHEMA, "design_id": uuid.uuid4().hex, "revision": 1, "template": template_id,\n            "name": name.strip(), "slug": slugify(name), "choices": ch, "intent": it, "created_at": now,\n            "updated_at": now}\n\n\ndef validate(doc) -> tuple[list[str], list[str]]:\n    """``(problems, unknown_fields)`` for a design read from disk. Problems make it unusable; unknown fields are\n    reported to the designer, never silently dropped."""\n    if not isinstance(doc, dict):\n        return ["the design is not a JSON object"], []\n    problems = []\n    if doc.get("schema") != DESIGN_SCHEMA:\n        problems.append("schema is %r; this factory reads %r" % (doc.get("schema"), DESIGN_SCHEMA))\n        return problems, []\n    unknown = sorted(set(doc) - DESIGN_KEYS)\n    rev = doc.get("revision")\n    if isinstance(rev, bool) or not isinstance(rev, int) or rev < 1:\n        problems.append("revision must be a whole number of at least 1")\n    try:\n        controls = _controls(str(doc.get("template")))\n    except DesignError as exc:\n        return problems + [str(exc)], unknown\n    for part in ("choices", "intent"):\n        if not isinstance(doc.get(part), dict):\n            problems.append("%s must be an object" % part)\n            continue\n        for key, value in doc[part].items():\n            c = controls.get(key)\n            if c is None:\n                unknown.append("%s.%s" % (part, key))\n                continue\n            try:\n                check_value(c, value)\n            except DesignError as exc:\n                problems.append(str(exc))\n    if not isinstance(doc.get("name"), str) or not doc["name"].strip():\n        problems.append("a level needs a name")\n    return problems, unknown\n\n\ndef write_design(folder: Path, doc: dict) -> Path:\n    """Save ``doc`` as ``folder/design.json``, atomically: the whole file or the previous one."""\n    folder.mkdir(parents=True, exist_ok=True)\n    path = folder / DESIGN_FILE\n    tmp = folder / (".design.%s.tmp" % uuid.uuid4().hex)\n    tmp.write_text(json.dumps(doc, ensure_ascii=False, indent=1) + "\\n", encoding="utf-8", newline="\\n")\n    os.replace(tmp, path)\n    return path\n\n\ndef read_design(path: Path) -> dict:\n    """``{"design", "problems", "unknown_fields", "path"}`` for a saved design; `DesignError` when it cannot be read."""\n    path = Path(path)\n    if path.is_dir():\n        path = path / DESIGN_FILE\n    try:\n        doc = json.loads(path.read_text(encoding="utf-8"))\n    except FileNotFoundError:\n        raise DesignError("no_design", "no design at %s" % path) from None\n    except (UnicodeDecodeError, json.JSONDecodeError) as exc:\n        raise DesignError("design_unreadable", "%s is not UTF-8 JSON: %s" % (path, exc)) from None\n    problems, unknown = validate(doc)\n    return {"design": doc, "problems": problems, "unknown_fields": unknown, "path": str(path)}\n\n\ndef free_folder(root: Path, slug: str) -> Path:\n    """``root/slug``, or ``root/slug_2``, ``_3``... -- a folder no design is in yet."""\n    n, folder = 1, Path(root) / slug\n    while (folder / DESIGN_FILE).exists():\n        n += 1\n        folder = Path(root) / ("%s_%d" % (slug, n))\n    return folder\n\n\n# ---- what the pipeline receives ---------------------------------------------------------------------------------\n\ndef mission_id(doc: dict) -> str:\n    return "%s_001" % doc["slug"]\n\n\ndef brief_from_design(doc: dict) -> dict:\n    """The mission brief the pipeline reads, derived from the design: the template\'s brief, the choices and the\n    intent laid over it, the mission named for the design. Notes travel as the brief\'s ``notes``."""\n    t = template(doc["template"])\n    brief = json.loads(json.dumps(t["brief"]))\n    brief["mission_id"] = mission_id(doc)\n    brief["display_name"] = doc["name"]\n    for key, value in doc["choices"].items():\n        brief[key] = value\n    for key, value in doc["intent"].items():\n        if key == "notes":\n            if value:\n                brief["notes"] = value\n            continue\n        brief[key] = value\n    if brief.get("road_grammar") == "T":\n        brief["road_grammar"] = ""\n    return brief\n', 'packages/service/templates/restaurant_row.json': '{\n  "schema": "gabagool.template.v1",\n  "template_id": "restaurant_row",\n  "label": "Restaurant Row",\n  "description": "A strip of three buildings on a street, anchored on a corner deli: a heist through the kitchen to the office safe, out by the alley. The factory\'s first level, built cold with nobody touching anything (cold runs 9222, 9391-9393).",\n  "batch": {\n    "seed_base": 9003,\n    "theme_family": "delco"\n  },\n  "brief": {\n    "schema": "level_factory.mission_brief.v0.1",\n    "archetype": "corner_deli",\n    "building_count": 3,\n    "site_shape": "strip",\n    "route_shape": "linear_push",\n    "objective_hypotheses": [\n      "enter_kitchen",\n      "reach_office",\n      "crack_safe",\n      "extract"\n    ],\n    "extraction_relationship": "alley_backtrack",\n    "verticality": "low",\n    "landmark": "neon_sign",\n    "time_of_day": "evening",\n    "weather": "clear",\n    "theme": "delco_1997",\n    "candidate_count": 3,\n    "target_minutes": [\n      25,\n      35\n    ]\n  }\n}\n', 'tests/service/test_design.py': '"""A level is a saved design, and its form tells the truth (0.245.0, the factory\'s roadmap 312 and 313).\n\nTwo promises, each held from both sides. THE CATALOG: every option a control offers is one its consumer knows, read\noff the owning code; every field nothing builds from is labelled intent; and a supported control\'s value reaches\nwhat the pipeline plans or builds. THE DESIGN: created, saved, reopened with every choice intact; a name used twice\nnever overwrites; unknown fields are reported, not dropped; the brief derived from the Restaurant Row template at its\ndefaults is the brief cold run 9222 built with nobody touching anything. FAILS ON 0.244.0: no design module.\n"""\nimport json\nimport sys\nfrom pathlib import Path\n\nimport pytest\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nfrom apps.cli.commands import UNBUILT_BRIEF_FIELDS, _brief_model, _preset_for  # noqa: E402\nfrom packages.pipeline import road_grammar, site_variation  # noqa: E402\nfrom packages.pipeline.planner import derive_seeds  # noqa: E402\nfrom packages.service import design, operations  # noqa: E402\nfrom packages.service.worker import RequestError  # noqa: E402\n\nT = "restaurant_row"\n_NOOP = type("E", (), {"emit": lambda self, *a, **k: None})()\n\n\ndef _controls():\n    return {c["key"]: c for c in design.capabilities(T)}\n\n\n# ---- the catalog ------------------------------------------------------------------------------------------------\n\ndef test_every_unbuilt_field_is_labelled_intent_and_nothing_else_is():\n    c = _controls()\n    intent = {k for k, v in c.items() if v["support"] == "intent"}\n    assert intent == set(UNBUILT_BRIEF_FIELDS) | {"notes"}\n    for k in intent:\n        assert c[k]["note"], k\n\n\ndef test_the_options_are_the_consumers_own():\n    c = _controls()\n    assert [o["value"] for o in c["road_grammar"]["options"]] == list(road_grammar.GRAMMARS)\n    assert [o["value"] for o in c["surroundings"]["options"]] == [""] + list(site_variation.SURROUNDINGS)\n    assert (c["candidate_count"]["min"], c["candidate_count"]["max"]) == design.CANDIDATES\n\n\ndef test_each_time_of_day_lights_the_level_differently():\n    presets = set()\n    for o in _controls()["time_of_day"]["options"]:\n        doc = design.new_design(T, "t", {"time_of_day": o["value"]})\n        presets.add(_preset_for(_brief_model(design.brief_from_design(doc))))\n    assert len(presets) == 5 and "Gas Station Fluorescent" not in presets      # none falls through to the default\n\n\ndef test_rain_is_conditional_and_says_what_it_replaces():\n    w = _controls()["weather"]\n    assert w["support"] == "conditional" and "replaces" in w["note"]\n    doc = design.new_design(T, "t", {"weather": "rain", "time_of_day": "midnight"})\n    assert _preset_for(_brief_model(design.brief_from_design(doc))) == "Heavy Rain"\n\n\ndef test_streets_and_layout_count_reach_the_pipeline():\n    doc = design.new_design(T, "t", {"road_grammar": "block", "candidate_count": 5})\n    brief = design.brief_from_design(doc)\n    assert road_grammar.grammar_of(brief["road_grammar"]) == "block"\n    assert len(derive_seeds(9003, _brief_model(brief).candidate_count)) == 5\n\n\ndef test_a_bad_value_or_an_unknown_control_is_refused():\n    with pytest.raises(design.DesignError):\n        design.new_design(T, "t", {"time_of_day": "dawn"})\n    with pytest.raises(design.DesignError):\n        design.new_design(T, "t", {"candidate_count": 99})\n    with pytest.raises(design.DesignError):\n        design.new_design(T, "t", {"verticality": "high"})          # intent is not a choice\n    with pytest.raises(design.DesignError):\n        design.new_design(T, "t", intent={"time_of_day": "noon"})   # nor a choice intent\n    with pytest.raises(design.DesignError):\n        design.new_design(T, "  ")\n\n\ndef test_the_template_at_its_defaults_is_the_first_level_brief():\n    from packages.tools import discovery\n    factory = discovery.factory_root()\n    if factory is None:\n        pytest.skip("this Level Factory stands outside a factory: no first-level brief to compare with")\n    first = json.loads((factory / "docs" / "first_level" / "briefs" / "restaurant_row_001.json").read_text(\n        encoding="utf-8"))\n    brief = design.brief_from_design(design.new_design(T, "Restaurant Row"))\n    for key, value in first.items():\n        if key in ("mission_id", "notes"):\n            continue\n        assert brief[key] == value, key\n\n\n# ---- the design -------------------------------------------------------------------------------------------------\n\n@pytest.fixture\ndef factory(tmp_path, monkeypatch):\n    from packages.tools import discovery\n    monkeypatch.setattr(discovery, "factory_root", lambda start=None: tmp_path)\n    return tmp_path\n\n\ndef test_create_save_reopen_keeps_every_choice(factory):\n    made = operations.create_design({"template": T, "name": "Night Shift",\n                                     "choices": {"time_of_day": "midnight", "road_grammar": "cross"},\n                                     "intent": {"notes": "a tired strip after closing"}}, _NOOP)\n    path = Path(made["path"])\n    assert path == factory / "levels" / "night_shift" / "design.json"\n    got = operations.open_design({"path": str(path.parent)}, _NOOP)\n    assert got["problems"] == [] and got["unknown_fields"] == []\n    assert got["design"] == made["design"]\n    assert got["design"]["choices"]["time_of_day"] == "midnight"\n    assert got["brief"]["notes"] == "a tired strip after closing"\n    assert got["brief"]["mission_id"] == "night_shift_001"\n\n\ndef test_a_name_used_twice_gets_its_own_folder(factory):\n    a = operations.create_design({"template": T, "name": "Twice"}, _NOOP)\n    b = operations.create_design({"template": T, "name": "Twice"}, _NOOP)\n    assert Path(a["path"]).parent.name == "twice" and Path(b["path"]).parent.name == "twice_2"\n    assert b["design"]["slug"] == "twice_2" and b["brief"]["mission_id"] == "twice_2_001"\n    listed = operations.list_designs({}, _NOOP)["designs"]\n    assert {Path(r["path"]).parent.name for r in listed} == {"twice", "twice_2"}\n\n\ndef test_unknown_fields_are_reported_and_a_wrong_schema_is_a_problem(factory):\n    made = operations.create_design({"template": T, "name": "Odd"}, _NOOP)\n    path = Path(made["path"])\n    doc = json.loads(path.read_text(encoding="utf-8"))\n    doc["colour_grade"] = "teal"\n    doc["choices"]["fog"] = 0.3\n    path.write_text(json.dumps(doc), encoding="utf-8")\n    got = operations.open_design({"path": str(path)}, _NOOP)\n    assert sorted(got["unknown_fields"]) == ["choices.fog", "colour_grade"]\n    assert got["design"]["colour_grade"] == "teal"                     # kept, not dropped\n    doc["schema"] = "gabagool.design.v0"\n    path.write_text(json.dumps(doc), encoding="utf-8")\n    got = operations.open_design({"path": str(path)}, _NOOP)\n    assert got["problems"] and got["brief"] is None\n\n\ndef test_operations_refuse_with_reasons(factory):\n    with pytest.raises(RequestError) as e:\n        operations.create_design({"template": "space_station", "name": "x"}, _NOOP)\n    assert e.value.code == "unknown_template"\n    with pytest.raises(RequestError) as e:\n        operations.open_design({"path": str(factory / "nowhere")}, _NOOP)\n    assert e.value.code == "no_design"\n    assert [t["template_id"] for t in operations.list_templates({}, _NOOP)["templates"]] == [T]\n    assert operations.describe_template({"template": T}, _NOOP)["controls"]\n', 'apps/godot/addons/gabagool_factory/level_panel.gd': '@tool\nextends VBoxContainer\n## The Level tab: start a level from a template, open a saved one, and see every control it has -- what each is\n## set to and whether it drives generation or only records intent (increment 3 of the no-AI authoring loop;\n## roadmap 312 and 313). A level is a design saved by the factory under `<factory>/levels/<name>/design.json`,\n## outside this project; the panel never writes it itself.\n##\n## Every action is a service operation through this panel\'s own client, one at a time: a request made while one is\n## running waits its turn (`_queue`). The last design opened is kept in the editor settings and opened again when\n## the panel next starts.\n\nconst ServiceClient := preload("res://addons/gabagool_factory/service_client.gd")\nconst SETTING_LAST := "gabagool_factory/last_design"\nconst SUPPORT_TEXT := {"supported": "drives generation", "conditional": "drives generation, with a condition",\n\t"intent": "intent only: saved, not built"}\nconst SUPPORT_COLOURS := {"supported": Color(0.45, 0.8, 0.45), "conditional": Color(0.95, 0.75, 0.3),\n\t"intent": Color(0.65, 0.65, 0.7)}\n\nvar client: Node\n## The design shown, as the factory last returned it ({} before one is opened).\nvar design: Dictionary = {}\nvar design_path: String = ""\nvar _templates: OptionButton\nvar _template_ids: Array = []\nvar _name: LineEdit\nvar _designs: OptionButton\nvar _design_paths: Array = []\nvar _info: Label\nvar _form: Tree\nvar _queue: Array = []\nvar _pending: Callable\n\n\nfunc _ready() -> void:\n\tname = "Level"\n\tclient = ServiceClient.new()\n\tadd_child(client)\n\tclient.finished.connect(_on_finished)\n\t_build()\n\n\nfunc _build() -> void:\n\tvar new_row := HBoxContainer.new()\n\t_templates = OptionButton.new()\n\tnew_row.add_child(_templates)\n\t_name = LineEdit.new()\n\t_name.placeholder_text = "Level name"\n\t_name.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\tnew_row.add_child(_name)\n\tvar create := Button.new()\n\tcreate.text = "New level"\n\tcreate.pressed.connect(new_level)\n\tnew_row.add_child(create)\n\tadd_child(new_row)\n\n\tvar open_row := HBoxContainer.new()\n\t_designs = OptionButton.new()\n\t_designs.size_flags_horizontal = Control.SIZE_EXPAND_FILL\n\topen_row.add_child(_designs)\n\tvar open := Button.new()\n\topen.text = "Open"\n\topen.pressed.connect(_open_selected)\n\topen_row.add_child(open)\n\tadd_child(open_row)\n\n\t_info = Label.new()\n\t_info.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART\n\tadd_child(_info)\n\n\t_form = Tree.new()\n\t_form.columns = 3\n\t_form.hide_root = true\n\t_form.column_titles_visible = true\n\t_form.set_column_title(0, "Control")\n\t_form.set_column_title(1, "Set to")\n\t_form.set_column_title(2, "What it does")\n\t_form.size_flags_vertical = Control.SIZE_EXPAND_FILL\n\tadd_child(_form)\n\n\n## Point the panel at a factory and load its templates and saved levels.\nfunc set_factory_root(root: String) -> void:\n\tclient.factory_root = root\n\tif root == "":\n\t\t_info.text = "Set up the factory first."\n\t\treturn\n\t_call("list_templates", {}, _on_templates)\n\t_refresh_designs()\n\tvar last := _setting(SETTING_LAST)\n\tif last != "":\n\t\topen_design(last)\n\n\nfunc _refresh_designs() -> void:\n\t_call("list_designs", {}, _on_designs)\n\n\n## Start a level from the chosen template, named from the name field (the template\'s name when blank).\nfunc new_level() -> void:\n\tif _template_ids.is_empty():\n\t\t_info.text = "No templates yet: the factory has not answered."\n\t\treturn\n\tvar template: String = _template_ids[_templates.selected]\n\tvar level_name := _name.text.strip_edges()\n\tif level_name == "":\n\t\tlevel_name = _templates.get_item_text(_templates.selected)\n\t_info.text = "Creating %s..." % level_name\n\t_call("create_design", {"template": template, "name": level_name}, _on_design)\n\n\n## Open the design at `path` (its folder or its design.json).\nfunc open_design(path: String) -> void:\n\t_info.text = "Opening %s..." % path\n\t_call("open_design", {"path": path}, _on_design)\n\n\nfunc _open_selected() -> void:\n\tif _design_paths.is_empty():\n\t\t_info.text = "No saved levels yet: start one with New level."\n\t\treturn\n\topen_design(_design_paths[_designs.selected])\n\n\nfunc _call(operation: String, arguments: Dictionary, done: Callable) -> void:\n\t_queue.append([operation, arguments, done])\n\t_next()\n\n\nfunc _next() -> void:\n\tif client.is_running() or _queue.is_empty():\n\t\treturn\n\tvar item: Array = _queue.pop_front()\n\t_pending = item[2]\n\tvar why: String = client.start(item[0], item[1])\n\tif why != "":\n\t\t_info.text = "Could not start: %s" % why\n\t\t_pending = Callable()\n\t\t_next()\n\n\nfunc _on_finished(result: Dictionary) -> void:\n\tvar done := _pending\n\t_pending = Callable()\n\tif result.get("status", "") != "ok":\n\t\tvar err: Dictionary = result.get("error", {}) if result.get("error") is Dictionary else {}\n\t\t_info.text = "The factory could not do that: %s" % err.get("message", "unknown error")\n\telif done.is_valid():\n\t\tdone.call(result.get("data", {}))\n\t_next()\n\n\nfunc _on_templates(data: Dictionary) -> void:\n\t_templates.clear()\n\t_template_ids.clear()\n\tfor t in data.get("templates", []):\n\t\tvar row: Dictionary = t\n\t\t_templates.add_item(row.get("label", row.get("template_id", "")))\n\t\t_template_ids.append(row.get("template_id", ""))\n\n\nfunc _on_designs(data: Dictionary) -> void:\n\t_designs.clear()\n\t_design_paths.clear()\n\tfor d in data.get("designs", []):\n\t\tvar row: Dictionary = d\n\t\tvar label := "%s (revision %s)" % [row.get("name", "?"), str(row.get("revision", "?"))]\n\t\tif row.get("problem") != null:\n\t\t\tlabel += " -- cannot be used: %s" % row.get("problem")\n\t\t_designs.add_item(label)\n\t\t_design_paths.append(row.get("path", ""))\n\n\nfunc _on_design(data: Dictionary) -> void:\n\tdesign = data.get("design", {})\n\tdesign_path = data.get("path", "")\n\t_set_setting(SETTING_LAST, design_path)\n\tvar problems: Array = data.get("problems", [])\n\tvar unknown: Array = data.get("unknown_fields", [])\n\tvar text := "%s -- revision %s, from %s. Saved at %s." % [design.get("name", "?"), str(design.get("revision", "?")),\n\t\tdesign.get("template", "?"), design_path]\n\tif not problems.is_empty():\n\t\ttext += "\\nCannot be built: %s" % "; ".join(problems)\n\tif not unknown.is_empty():\n\t\ttext += "\\nFields this factory does not know (kept as they are): %s" % ", ".join(unknown)\n\t_info.text = text\n\t_refresh_designs()\n\t_call("describe_template", {"template": design.get("template", "")}, _on_controls)\n\n\nfunc _on_controls(data: Dictionary) -> void:\n\t_form.clear()\n\tvar root := _form.create_item()\n\tvar choices: Dictionary = design.get("choices", {})\n\tvar intent: Dictionary = design.get("intent", {})\n\tfor c in data.get("controls", []):\n\t\tvar control: Dictionary = c\n\t\tvar key: String = control.get("key", "")\n\t\tvar item := _form.create_item(root)\n\t\titem.set_text(0, control.get("label", key))\n\t\tvar value: Variant = design.get("name", "") if key == "name" else choices.get(key, intent.get(key, ""))\n\t\titem.set_text(1, _shown(control, value))\n\t\tvar support: String = control.get("support", "")\n\t\tvar what: String = SUPPORT_TEXT.get(support, support)\n\t\titem.set_text(2, what)\n\t\titem.set_custom_color(2, SUPPORT_COLOURS.get(support, Color.WHITE))\n\t\tvar tip: String = str(control.get("note", control.get("consumer", "")))\n\t\titem.set_tooltip_text(2, tip)\n\n\n## A control\'s value as the form shows it: an option\'s label, yes/no, a list joined.\nstatic func _shown(control: Dictionary, value: Variant) -> String:\n\tif value is Array:\n\t\treturn ", ".join(value)\n\tif value is bool:\n\t\treturn "yes" if value else "no"\n\tfor o in control.get("options", []):\n\t\tvar option: Dictionary = o\n\t\tif option.get("value") == value:\n\t\t\treturn str(option.get("label", value))\n\treturn str(value)\n\n\nfunc _setting(key: String) -> String:\n\tif not Engine.is_editor_hint():\n\t\treturn ""\n\tvar es := EditorInterface.get_editor_settings()\n\treturn str(es.get_setting(key)) if es.has_setting(key) else ""\n\n\nfunc _set_setting(key: String, value: String) -> void:\n\tif Engine.is_editor_hint():\n\t\tEditorInterface.get_editor_settings().set_setting(key, value)\n', 'apps/godot/addons/gabagool_factory/level_panel.gd.uid': 'uid://b4uvpjte5ui4a\n', 'apps/godot/tests/test_level_panel.gd': 'extends SceneTree\n## The Level tab, headless, against the real factory: it lists the templates, starts a level, shows every control\n## with whether it drives generation or only records intent, and opens the saved level again.\n##\n##     godot --headless --path <this project> --script res://tests/test_level_panel.gd -- [<python> <cli main.py>]\n##\n## The level it makes is its own: named for this run, under `<factory>/levels/`, and deleted at the end. Prints PASS\n## or FAIL lines; quits 0 only when every case passed.\n\nconst LevelPanel := preload("res://addons/gabagool_factory/level_panel.gd")\nconst FactoryDock := preload("res://addons/gabagool_factory/factory_dock.gd")\n\nvar _failures := 0\n\n\nfunc _initialize() -> void:\n\t_run.call_deferred()\n\n\nfunc _check(ok: bool, what: String) -> void:\n\tprint(("PASS " if ok else "FAIL ") + what)\n\tif not ok:\n\t\t_failures += 1\n\n\nfunc _settle(panel: Node) -> void:\n\t# until the panel\'s queue is empty and its client idle\n\tfor i in range(2400):\n\t\tawait process_frame\n\t\tif not panel.client.is_running() and panel._queue.is_empty():\n\t\t\treturn\n\n\nfunc _run() -> void:\n\tvar factory := FactoryDock.find_factory_root(ProjectSettings.globalize_path("res://"))\n\tvar panel: Control = LevelPanel.new()\n\troot.add_child(panel)\n\tvar user_args := OS.get_cmdline_user_args()\n\tif user_args.size() >= 2:\n\t\tpanel.client.launch_prefix = PackedStringArray([user_args[0], user_args[1]])\n\tpanel.set_factory_root(factory)\n\tawait _settle(panel)\n\t_check(panel._template_ids.has("restaurant_row"), "the templates include Restaurant Row: %s" % [panel._template_ids])\n\n\tvar level_name := "godot test level %d" % Time.get_ticks_usec()\n\tpanel._name.text = level_name\n\tpanel.new_level()\n\tawait _settle(panel)\n\tvar made: Dictionary = panel.design\n\t_check(made.get("revision") == 1 and made.get("name") == level_name, "a new level is revision 1: %s" % made.get("name"))\n\t_check(FileAccess.file_exists(panel.design_path), "it is saved by the factory: %s" % panel.design_path)\n\tvar rows: Array = panel._form.get_root().get_children() if panel._form.get_root() != null else []\n\t_check(rows.size() >= 10, "the form shows every control (%d)" % rows.size())\n\tvar said: Array = rows.map(func(it: TreeItem) -> String: return it.get_text(2))\n\t_check(said.has("drives generation") and said.has("intent only: saved, not built"),\n\t\t"each control says whether it drives generation or only records intent")\n\tvar time_row: Array = rows.filter(func(it: TreeItem) -> bool: return it.get_text(0) == "Time of day")\n\t_check(time_row.size() == 1 and time_row[0].get_text(1) == "Evening", "Time of day shows the template\'s Evening")\n\n\tvar path: String = panel.design_path\n\tpanel.design = {}\n\tpanel.open_design(path)\n\tawait _settle(panel)\n\t_check(panel.design.get("design_id") == made.get("design_id"), "opening it again gives the same level")\n\t_check(panel._design_paths.has(path), "it is listed among the saved levels")\n\n\t# the level is this test\'s: remove its folder\n\tvar folder := path.get_base_dir()\n\tfor f in DirAccess.get_files_at(folder):\n\t\tDirAccess.remove_absolute(folder.path_join(f))\n\tDirAccess.remove_absolute(folder)\n\t_check(not DirAccess.dir_exists_absolute(folder), "the test\'s level is removed")\n\tpanel.queue_free()\n\tprint("DONE failures=%d" % _failures)\n\tquit(1 if _failures else 0)\n', 'apps/godot/tests/test_level_panel.gd.uid': 'uid://c5wf8kkfo7e4d\n'}
CHANGELOG = "## [0.245.0] - a level is a saved design, and the panel's form tells the truth\n\n**Increment 3 of the no-AI authoring loop** (the factory's `docs/AUTHORING_LOOP.md`; roadmap 312 and 313).\n\n### Added\n- **The design document** (`packages/service/design.py`, `gabagool.design.v1`). A level's authored source: its\n  template, its choices, its intent, a stable `design_id` and a revision number. It is saved by the factory as\n  `<factory>/levels/<slug>/design.json`, written atomically, outside the Godot project and the tool repos.\n  - A name used twice gets a numbered folder, never an overwrite.\n  - Reading one reports fields this factory does not know without dropping them, and lists what makes it\n    unusable.\n  - The brief the pipeline reads is derived from it (`brief_from_design`); the Restaurant Row template at its\n    defaults gives the first-level brief cold run 9222 built with no interventions.\n- **Templates** (`packages/service/templates/`), starting with Restaurant Row.\n- **The capability catalog** (`design.capabilities`). Each control has a type, options or range, default, consumer,\n  what it rebuilds, and a support state:\n  - supported: name, time of day, streets, beyond the edge, layouts to generate, roof clutter;\n  - conditional: weather (rain replaces the time of day with Heavy Rain);\n  - intent: the six recorded-but-unbuilt brief fields and notes.\n\n  Options are read off their owners: `road_grammar.GRAMMARS`, `site_variation.SURROUNDINGS`, the five times\n  `_preset_for` resolves. A bad value or a control the template lacks is refused.\n- **Operations**: `list_templates`, `describe_template`, `create_design`, `open_design`, `list_designs`.\n- **The Level tab** on the panel (`apps/godot/addons/gabagool_factory/level_panel.gd`). Start a level from a\n  template, open a saved one, and see every control with its value and whether it drives generation or only records\n  intent. The last level opened is opened again next time.\n  The dock's 0.244.0 controls move to a Setup tab.\n\n### Tests\n- `tests/service/test_design.py` (fails on 0.244.0):\n  - every unbuilt field labelled intent; options equal to their owners';\n  - each time of day a distinct Lux preset; rain's substitution; streets and layout count reaching the pipeline;\n  - refusals; the first-level brief reproduced;\n  - create, save and reopen keeping every choice; a reused name; unknown fields kept and reported.\n- `apps/godot/tests/test_level_panel.gd`: the Level tab against a real factory (create, show, reopen, then its own\n  level removed).\n\n"
OLD_VERSION, NEW_VERSION = '0.244.0', '0.245.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
